  done
  loc=$(curl -s -o /dev/null -w '%{redirect_url}' "$base/quiz.html" || true)
  [[ "$loc" == */quiz ]] && r=ok || r=bad
  check "$base/quiz.html still leads to /quiz" "$r" "next.config.ts redirects didn't deploy."
  loc=$(curl -s -o /dev/null -w '%{redirect_url}' "$base/account" || true)
  [[ "$loc" == */login* ]] && r=ok || r=bad
  check "$base/account asks visitors to sign in" "$r" "proxy.ts didn't run; check the build log."
done
settings=$(curl -s "$URL/auth/v1/settings" -H "apikey: $LIVE_KEY" || true)
[[ "$settings" == *'"disable_signup":false'* ]] && r=ok || r=bad
check "Students can sign up" "$r" "$SB_DASH/auth/providers → 'Allow new users to sign up' ON."
[[ "$settings" == *'"mailer_autoconfirm":false'* ]] && r=ok || r=bad
check "Students must confirm their email" "$r" "$SB_DASH/auth/providers → Email → 'Confirm email' ON."
[[ "$settings" == *'"google":true'* ]] && r=ok || r=bad
check "Google sign-in is on" "$r" "Redo stage 9."
printf '\n'; say "Now by hand, on a phone and a computer (SPEC-2 §5 and §6):"
step "Contact form on $SITE: name 'TEST – Claude', message"
step "  'رسالة اختبار بعد إطلاق موقع Next.js – يمكن تجاهلها'. It must show up in /admin → Messages."
step "Sign up with an email you control: the confirmation email comes from $ADMIN and its button signs you in."
step "Forgot password with the same account: the reset email arrives and the new password works."
step "Sign up with Google, then fill in name, WhatsApp and student group."
pause "Press Enter when these work (note anything that doesn't)"

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Frau Asmaa adds her courses"
open_url "$SITE/admin/courses"
step "Frau Asmaa signs in with the account from stage 10 and adds her courses. New courses start hidden."
step "She shows a course when it's ready; the home page lists only shown courses."
step "Test booking: sign in as the test student from stage 15, book a shown course."
step "Frau Asmaa and the student both get an email; the booking shows in /admin and in /account."
step "Then set that test booking to مقفول (don't delete it)."
note "If an email doesn't arrive, /admin shows 'email not sent' on the booking: send Claude the message there."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
